self.KB_CONTENT["card:838231"]={"id":"card:838231","ty":"card","sourceId":"838231","title":"如何修改進貨單稅額","ver":"GP4 以上","topic":"進貨單","keywords":["進貨單","單身","稅額","共用"],"y":"howto","answer":"若要修改進貨單身稅額，『共用參數設定作業』的【稅額計算方式】須為單身單筆資料計算","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
