self.KB_CONTENT["card:791569"]={"id":"card:791569","ty":"card","sourceId":"791569","title":"『費用預估建立作業』中的『費用代號 (UG005)』為何？","ver":"GP4以上","topic":"費用","keywords":["費用","類型"],"y":"other","answer":"* 不可空白，可不存在。* 若類型為「1.費用」，可按[F2] 費用代號查詢。* 若類型為「2.加扣項」，可按[F2] 加扣款代號查詢。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
