self.KB_CONTENT["field:834994"]={"id":"field:834994","ty":"field","sourceId":"834994","title":"預計銷","ver":"iGP 1.0.14以上","topic":"","keywords":[],"job":"庫存狀況查詢作業","code":"","answer":"預計銷=訂單數量-已交訂量+贈備品量-贈備品已交量-暫出數量+歸還量+轉進銷量-暫出贈/備品量+歸還贈/備品量+轉銷贈/備品量","file":"fields.jsonl"};
