self.KB_CONTENT["field:875328"]={"id":"field:875328","ty":"field","sourceId":"875328","title":"進口費用資料子單頭","ver":"GPGP4.0.12以上","topic":"","keywords":[],"job":"進口費用建立作業","code":"","answer":"可透過『進口費用自動結帳作業』產生應付憑單，因應付憑單單頭僅一個【發票號碼】欄位，故若子單頭多費用都有輸入發票號碼，則會分開產生應付憑單。","file":"fields.jsonl"};
